// Copyright 2024 the Dart project authors. All rights reserved.// Use of this source code is governed by a BSD-style license// that can be found in the LICENSE file.import 'dart:math' as math;import 'package:flame/components.dart';import 'package:flame/events.dart';import 'package:flame/game.dart';import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'components/ball.dart';import 'components/brick.dart';import 'components/paddle.dart';import 'components/play_area.dart';import 'config.dart';class BrickBreaker extends FlameGame    with HasCollisionDetection, KeyboardEvents, TapCallbacks {  BrickBreaker()    : super(        camera: CameraComponent.withFixedResolution(          width: gameWidth,          height: gameHeight,        ),      );  final rand = math.Random();  double get width => size.x;  double get height => size.y;  @override  void onLoad() {    super.onLoad();    camera.viewfinder.anchor = Anchor.topLeft;    world.add(PlayArea());    startGame();  }  void startGame() {    world.removeAll(world.children.query<Ball>());    world.removeAll(world.children.query<Paddle>());    world.removeAll(world.children.query<Brick>());    world.add(      Ball(        difficultyModifier: difficultyModifier,        radius: ballRadius,        position: size / 2,        velocity: Vector2(          (rand.nextDouble() - 0.5) * width,          height * 0.3,        ).normalized()..scale(height / 4),      ),    );    world.add(      Paddle(        size: Vector2(paddleWidth, paddleHeight),        cornerRadius: const Radius.circular(ballRadius / 2),        position: Vector2(width / 2, height * 0.95),      ),    );    world.addAll([      for (var i = 0; i < brickColors.length; i++)        for (var j = 1; j <= 5; j++)          Brick(            Vector2(              (i + 0.5) * brickWidth + (i + 1) * brickGutter,              (j + 2.0) * brickHeight + j * brickGutter,            ),            brickColors[i],          ),    ]);  }  @override  void onTapDown(TapDownEvent event) {    super.onTapDown(event);    startGame();  }  @override  KeyEventResult onKeyEvent(    KeyEvent event,    Set<LogicalKeyboardKey> keysPressed,  ) {    super.onKeyEvent(event, keysPressed);    switch (event.logicalKey) {      case LogicalKeyboardKey.space:      case LogicalKeyboardKey.enter:        startGame();    }    return KeyEventResult.handled;  }  @override  Color backgroundColor() => const Color(0xfff2e8cf);}